css:
.loader { display: inline-flex; align-items: center; gap: calc(var(--loader-size) * .07); padding: calc(var(--loader-size) * .1) calc(var(--loader-size) * .13); border-radius: calc(var(--loader-size) * .22) calc(var(--loader-size) * .22) calc(var(--loader-size) * .22) calc(var(--loader-size) * .05); background: color-mix(in srgb, var(--loader-color) 16%, transparent); }
.loader span { width: calc(var(--loader-size) * .1); height: calc(var(--loader-size) * .1); border-radius: 9999px; background: var(--loader-color); animation: twBlink calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .4); }
@keyframes twBlink { 0%, 100% { opacity: .3; transform: translateY(0); } 40% { opacity: 1; transform: translateY(-28%); } }
